    q("8", "من سجل هدفي فوز أياكس بنهائي روتردام 1972 ضد إنتر ميلان لينتصر الفريق بنتيجة 2-0؟", "يوهان كرويف", "بيت كايزر", "جيري موهرين", "جوني ريب"),
    q("8", "من كان كابتن بايرن ميونخ الذي رفع كؤوس أوروبا الثلاث المتتالية بين 1974 و1976؟", "فرانز بيكنباور", "سيب ماير", "بول برايتنر", "غيرد مولر"),
    q("8", "من كان مدرب ليدز يونايتد الإنجليزي في نهائي باريس المثير للجدل 1975 عندما خسر 2-0 أمام بايرن؟", "جيمي أرمفيلد", "دون ريفي", "برايان كلوف", "جوك شتاين"),
    q("8", "في أي عام ميلادي توج نادي هامبورغ الألماني بلقبه الوحيد في كأس الأندية الأوروبية البطلة؟", "1983", "1982", "1984", "1980"),
    q("8", "من كان المدير الفني لنادي يوفنتوس في نهائي أثينا 1983 عندما خسر الفريق أمام هامبورغ؟", "جيوفاني تراباتوني", "تشيزاري مالديني", "إنزو بيرزوت", "أوزفالدو باغنولي"),
    q("8", "في أي مدينة إيطالية توج ليفربول بلقب كأس أوروبا عام 1984 على الاستاد الأولمبي ضد ذئاب العاصمة؟", "روما", "ميلانو", "تورينو", "باري"),
    q("8", "من كان حارس ليفربول صاحب رقصة الساقين الشهيرة في ركلات ترجيح نهائي روما 1984؟", "بروس غروبيلار", "راي كليمنس", "ديفيد جيمس", "جيرزي دوديك"),
    q("8", "من كان مدرب ليفربول الذي حقق لقب كأس أوروبا عام 1984 في أول موسم له خلفاً لبيسلي؟", "جو فاغان", "بوب بيسلي", "كيني دالغليش", "كولن هارفي"),
    q("8", "في أي عام توج نادي بورتو البرتغالي بلقبه الأوروبي الأول بعد الفوز على بايرن ميونخ 2-1 في فيينا؟", "1987", "1986", "1988", "1985"),
    q("8", "في أي عام توج النجم الأحمر بلغراد بلقب كأس أوروبا بعد الفوز بركلات الترجيح على مارسيليا؟", "1991", "1990", "1992", "1989"),
    q("8", "من هو المهاجم المقدوني الذي سجل ركلة الترجيح الخامسة الحاسمة للنجم الأحمر في نهائي 1991؟", "داركو بانشيف", "روبرت بروزينيتشكي", "ديان سافيتشيفيتش", "سينيشا ميهايلوفيتش"),
    q("8", "من كان المدير الفني لبرشلونة عندما حقق لقبه الأوروبي الأول عام 1992 في ويمبلي أمام سامبدوريا؟", "يوهان كرويف", "لويس فان غال", "تيري فينابلز", "لويس أراغونيس"),
    q("8", "من سجل هدف برشلونة التاريخي بضربة حرة صاروخية بالدقيقة 112 بنهائي ويمبلي 1992؟", "رونالد كومان", "خريستو ستويتشكوف", "مايكل لاودروب", "خوسيه ماري باكيرو"),
  ];

  print("Total questions created: ${questions.length}");

  // Group by level
  final Map<String, int> countsByLevel = {};
  for (final item in questions) {
    final lvl = item["Level"] as String;
    countsByLevel[lvl] = (countsByLevel[lvl] ?? 0) + 1;
  }

  print("Counts by level:");
  countsByLevel.keys.toList()..sort()..forEach((k) => print("  Level $k: ${countsByLevel[k]}"));

  // Expected level distribution
  final expected = {
    "0": 34,
    "1": 33,
    "2": 33,
    "4": 33,
    "5": 33,
    "6": 34,
    "3": 33,
    "7": 33,
    "8": 34,
  };

  expected.forEach((lvl, expectedCount) {
    final actual = countsByLevel[lvl] ?? 0;
    if (actual != expectedCount) {
      throw Exception("Level $lvl count mismatch: expected $expectedCount, got $actual");
    }
  });

  // Tiers check
  final tier0 = (countsByLevel["0"] ?? 0) + (countsByLevel["1"] ?? 0) + (countsByLevel["2"] ?? 0);
  final tier1 = (countsByLevel["4"] ?? 0) + (countsByLevel["5"] ?? 0) + (countsByLevel["6"] ?? 0);
  final tier2 = (countsByLevel["3"] ?? 0) + (countsByLevel["7"] ?? 0) + (countsByLevel["8"] ?? 0);
  print("Tier 0 total: $tier0 (expected 100)");
  print("Tier 1 total: $tier1 (expected 100)");
  print("Tier 2 total: $tier2 (expected 100)");

  assert(tier0 == 100);
  assert(tier1 == 100);
  assert(tier2 == 100);

  // Quality checks:
  final Set<String> questionTexts = {};
  int leakCount = 0;
  for (int i = 0; i < questions.length; i++) {
    final qItem = questions[i];
    final qText = qItem["Q"] as String;
    final r = qItem["R"] as String;
    final w1 = qItem["W1"] as String;
    final w2 = qItem["W2"] as String;
    final w3 = qItem["W3"] as String;

    if (!qText.endsWith("؟")) {
      throw Exception("Question #$i does not end with '؟': $qText");
    }

    if (qText.contains("اكتب الرقم") || qText.contains("اختر") || qText.contains("ما رأيك")) {
      throw Exception("Question #$i contains forbidden phrase: $qText");
    }

    if (questionTexts.contains(qText)) {
      throw Exception("Duplicate question found at #$i: $qText");
    }
    questionTexts.add(qText);

    final set = {r, w1, w2, w3};
    if (set.length != 4) {
      throw Exception("Question #$i has duplicate options: R='$r', W1='$w1', W2='$w2', W3='$w3'");
    }

    // Leak check (R appearing inside Q):
    // Ignore cases where R is short numbers like "3" or "4" matching inside "2024"
    bool leak = false;
    if (r.length > 3 && qText.contains(r)) {
      leak = true;
    }
    if (leak) {
      print("Potential leak in #$i: Q='$qText' contains R='$r'");
      leakCount++;
    }
  }

  print("Total distinct questions: ${questionTexts.length}");
  print("Potential leaks: $leakCount");
  if (leakCount > 0) {
    throw Exception("Leaks found! Please resolve before continuing.");
  }

  // Write JSON to file
  final jsonStr = JsonEncoder.withIndent("  ").convert(questions);
  final outFile = File("assets/questions_ucl_300.json");
  outFile.writeAsStringSync(jsonStr, encoding: utf8);
  print("Successfully saved 300 questions to ${outFile.path}");
}
